def get_bid(day_context, my_status, opponents_status):
    WATER_REQ = 13
    DAILY_SALARY = 70
    supply = day_context['supply']
    day = day_context['day']
    hp = my_status['hp']
    budget = my_status['budget']
    no_water_days = my_status['no_water_days']

    if budget <= 0:
        return 0.0

    alive = []
    prev_bids = []
    strong_prev = []
    for agent_id, opp in opponents_status.items():
        if opp.get('alive'):
            alive.append(opp)
            prev = opp.get('previous_trace', {}) or {}
            bid = prev.get('bid')
            if bid is not None:
                prev_bids.append(float(bid))
                if float(bid) >= 100:
                    strong_prev.append(float(bid))

    alive_count = len(alive)
    if alive_count == 0:
        return float(min(budget, 18.0))

    guaranteed_slots = int(supply // WATER_REQ)
    scarcity = guaranteed_slots < alive_count

    highest_prev = max(prev_bids) if prev_bids else 0.0
    avg_prev = (sum(prev_bids) / len(prev_bids)) if prev_bids else 0.0

    emergency = hp <= 3 or no_water_days >= 1
    critical = hp <= 2 or no_water_days >= 2

    if critical:
        target = max(130.0, highest_prev + 8.0)
    elif emergency:
        target = max(105.0, highest_prev + 4.0)
    else:
        if scarcity:
            if highest_prev >= 170:
                target = 118.0 if hp >= 6 else 145.0
            elif highest_prev >= 120:
                target = highest_prev + 3.0
            elif highest_prev > 0:
                target = max(88.0, avg_prev + 6.0)
            else:
                target = 82.0
        else:
            if hp >= 7 and no_water_days == 0:
                target = 28.0
            else:
                target = 52.0

    if day >= 8:
        target += 8.0
    if budget < 140:
        target = min(target, budget * 0.72)
    elif budget < 220:
        target = min(target, budget * 0.82)
    else:
        target = min(target, budget * 0.9)

    floor_bid = 0.0
    if emergency:
        floor_bid = 60.0
    elif scarcity:
        floor_bid = 40.0
    else:
        floor_bid = 18.0

    bid = max(floor_bid, target)
    bid = min(bid, budget)
    if bid < 0:
        bid = 0.0
    return float(round(bid, 2))

def get_bid(day_context, my_status, opponents_status):
    WATER_REQ = 8
    DAILY_SALARY = 140
    MAX_SUPPLY = 25
    MIN_SUPPLY = 15

    supply = day_context['supply']
    day = day_context['day']
    hp = my_status['hp']
    budget = my_status['budget']
    no_water_days = my_status['no_water_days']

    alive_opponents = {k: v for k, v in opponents_status.items() if v['alive']}
    if not alive_opponents:
        return min(budget, DAILY_SALARY * 0.4)

    # Gather yesterday's bids from alive opponents
    yesterday_bids = []
    for opp in alive_opponents.values():
        prev = opp.get('previous_trace', {})
        if prev and prev.get('bid') is not None:
            yesterday_bids.append(prev['bid'])

    # Determine last day's highest bid among opponents
    highest_prev = max(yesterday_bids) if yesterday_bids else 0.0

    # Base bid determined by urgency
    # Urgency: need water if no_water_days >= 1 or hp is critically low
    urgency = 0.0
    if no_water_days > 0:
        urgency += 0.3 * no_water_days
    if hp <= 3:
        urgency += 0.5
    elif hp <= 5:
        urgency += 0.3
    else:
        urgency += 0.1

    # Safety cap: never bid more than 90% of budget or 2x salary, whichever is smaller
    max_bid = min(budget * 0.9, DAILY_SALARY * 2.0)

    # If we are desperate, bid just above highest previous bid (if we can afford)
    if urgency >= 0.8:
        target_bid = highest_prev + 2.0
        return min(max_bid, target_bid)

    # Moderate urgency: bid a bit above average of previous highest and our salary-based estimate
    if urgency >= 0.4:
        # Strategic bid: if they bid very high, undercut by 10% to let them waste
        if highest_prev > DAILY_SALARY * 1.2:
            target_bid = highest_prev * 0.9
        else:
            target_bid = max(highest_prev + 1.0, DAILY_SALARY * 0.6)
        return min(max_bid, target_bid)

    # Low urgency: bid conservatively
    # If yesterday's highest bid was very high, we can even bid lower to save
    if highest_prev > DAILY_SALARY * 1.3:
        target_bid = DAILY_SALARY * 0.4
    else:
        target_bid = DAILY_SALARY * 0.5
    return min(budget, target_bid)
